// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The reference owner() returns msg.sender initially (the deployer)
        // We will transfer ownership to a specific address (e.g., 0xdead)
        address newOwner = address(0xdead);
        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);
        // Now, in the reference, owner() returns newOwner; in the bug, owner() returns address(0).
        // We will call acceptOwnership() as newOwner (so it should succeed in reference)
        bool ok;
        vm.prank(newOwner);
        try c.acceptOwnership() {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, acceptOwnership() succeeds (ok == true).
        // In the bug, owner() returns address(0), so pendingOwner (newOwner) != owner (0), so it reverts with OwnableUnauthorizedAccount, making ok == false.
        assertTrue(ok);
    }
}

