pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the scenario: deploy and initialize the contract
        // Note: C is an upgradeable contract with __Ownable_init(msg.sender) called in initialize().
        // We need to call initialize() to set up the contract.
        // The initialize function requires credChainId, credId, verificationType, protocolFeeDestination.
        // We provide dummy values.
        vm.prank(address(this));
        c.initialize(1, 1, "test", address(this));

        // Now the owner is this contract (the test).
        // Initiate ownership transfer to address(1).
        address newOwner = address(1);
        c.transferOwnership(newOwner);

        // Check that pendingOwner is set correctly
        assertEq(c.pendingOwner(), newOwner);

        // Now prank as the pending owner and call acceptOwnership()
        vm.prank(newOwner);
        c.acceptOwnership();

        // After acceptOwnership, the new owner should be newOwner
        // In the reference contract, this succeeds; in the mutant, it also succeeds (no revert difference).
        // The difference is in paused() return value: reference returns actual paused state, mutant always false.
        // Since we never paused the contract, both return false. To expose the bug we need a scenario where contract IS paused.
        // Let's pause the contract first.

        // Reset: deploy new instance
        c = new C();
        vm.prank(address(this));
        c.initialize(1, 1, "test", address(this));

        // Pause the contract (only owner can, and we are owner)
        c.pause();

        // Now paused() should return true in reference, false in mutant.
        // This is a public view function, so we can assert on it.
        bool actualPaused = c.paused();
        // In reference, this is true; in mutant, it's false.
        // We assert the expected reference behavior: paused() returns true.
        assertTrue(actualPaused);
    }
}

