pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deploy, initialize, then pause the contract
        // The contract uses the initializer modifier, so we need to call initialize first
        // However, the constructor of C calls _disableInitializers, so we cannot initialize again.
        // To make the test work, we need to simulate the state where the contract is paused.
        // Since we cannot call initialize (it will revert with InvalidInitialization), we need to work
        // with the contract as is after constructor. But the contract is not paused after construction.
        // We will directly call pause() which requires onlyOwner; in setUp we own the contract.

        // First, we need to set the owner to a known address
        // By default, the owner is address(this) (the test contract)

        // Pause the contract
        vm.prank(address(this));
        c.pause();

        // Now, we attempt to call acceptOwnership()
        // acceptOwnership() transfers ownership; it does not call _update directly, but
        // it does call _transferOwnership which calls super._transferOwnership.
        // However, the contract's safeTransferFrom and safeBatchTransferFrom are overridden
        // to check soulBounded, but they only block transfers if the token is soulbound.
        // acceptOwnership itself does not call any ERC1155 transfer.
        // The paused() function is not called anywhere in acceptOwnership.
        // So the test described is not actually triggering paused() in acceptOwnership.
        // 
        // Based on the provided description, the difference is in paused() return value.
        // We need a different entry point that actually uses paused().
        // The contract has a modifier whenNotPaused used in createArtFromFactory and claimFromFactory,
        // but those require msg.sender to be the phiFactoryContract.
        // 
        // The standard ERC1155PausableUpgradeable overrides _update with whenNotPaused.
        // So any transfer (mint, burn, safeTransferFrom, safeBatchTransferFrom) will check paused().
        // If the contract is paused, safeTransferFrom should revert.
        // The buggy paused() always returns false, so it will not revert.
        // 
        // Let's test with safeTransferFrom:
        // 1. Mint a token to an address (via mint function, which is internal, so we need to call
        //    a public function that mints). The only way to mint is through claimFromFactory, which
        //    requires msg.sender to be phiFactoryContract. We cannot set that easily.
        // Alternatively, we can directly call _mint? No, it's internal.
        // 
        // Another approach: use the pause() and unpause() functions themselves.
        // But paused() is not called by acceptOwnership.
        // 
        // Given the constraints, the only viable test is to check the return of paused() directly.
        // In the reference, paused() returns true when paused; in the bug it returns false.
        // So we can simply assert that paused() returns true.

        bool isPaused = c.paused();
        assertTrue(isPaused);
    }
}

